interface Document {
  id: string;
  documentUrl: string;
  projectId: string;
  projectName: string;
  date: number;
  description: string;
}

import {
  collection,
  doc,
  increment,
  setDoc,
  updateDoc,
} from 'firebase/firestore';
import { db } from './config';

/**
 * Creates a new transaction document in the root transactions collection
 * @param transaction - The transaction data (must include userId)
 * @returns The generated transaction ID
 */
export async function createTransaction(
  transaction: Transaction,
): Promise<string> {
  try {
    // Get root transactions collection reference
    const transactionsRef = collection(db, 'transactions');

    // Generate a new document reference with auto-generated ID from Firestore
    const newDocRef = doc(transactionsRef);
    const transactionId = newDocRef.id;

    // Write to root transactions collection
    await setDoc(newDocRef, transaction);

    // Update project's moneyRaised if it's an investment
    if (transaction.type === 'investment') {
      const projectRef = doc(db, 'projects', transaction.projectId);
      await updateDoc(projectRef, {
        moneyRaised: increment(transaction.amount),
      });
    }

    console.log('Transaction created:', transactionId);
    return transactionId;
  } catch (error) {
    console.error('Error creating transaction:', error);
    throw error;
  }
}

/**
 * Creates an investment transaction
 * @param projectId - The project ID
 * @param projectName - The project name
 * @param amount - The investment amount
 * @param accountName - The account name
 * @param description - The transaction description
 * @param userId - The user ID
 * @param userEmail - The user email
 * @returns The generated transaction ID
 */
export async function createInvestmentTransaction(
  projectId: string,
  projectName: string,
  amount: number,
  accountName: string,
  description: string,
  userId: string,
  userEmail: string,
): Promise<string> {
  const transaction: Transaction = {
    type: 'investment',
    projectId,
    projectName,
    amount,
    accountName,
    date: Date.now(),
    description,
    userId,
    userEmail,
  };

  return createTransaction(transaction);
}

/**
 * Creates a return transaction
 * @param projectId - The project ID
 * @param projectName - The project name
 * @param amount - The return amount
 * @param accountName - The account name
 * @param description - The transaction description
 * @param userId - The user ID
 * @param userEmail - The user email
 * @returns The generated transaction ID
 */
export async function createReturnTransaction(
  projectId: string,
  projectName: string,
  amount: number,
  accountName: string,
  description: string,
  userId: string,
  userEmail: string,
): Promise<string> {
  const transaction: Transaction = {
    type: 'return',
    projectId,
    projectName,
    amount,
    accountName,
    date: Date.now(),
    description,
    userId,
    userEmail,
  };

  return createTransaction(transaction);
}

