import {
  arrayRemove,
  arrayUnion,
  doc,
  DocumentSnapshot,
  getDoc,
  setDoc,
  updateDoc,
} from 'firebase/firestore';
import { db } from './config';

export interface UserDocument {
  uid: string;
  email: string;
  displayName?: string;
  createdAt: number;
  updatedAt: number;
  photoURL?: string;
}

/**
 * Checks if a user document exists in Firestore
 * @param userId - The user ID to check
 * @returns True if the document exists, false otherwise
 */
export async function userDocumentExists(userId: string): Promise<boolean> {
  try {
    const userRef = doc(db, 'users', userId);
    const userSnap: DocumentSnapshot = await getDoc(userRef);
    return userSnap.exists();
  } catch (error) {
    console.error('Error checking user document:', error);
    throw error;
  }
}

/**
 * Creates a new user document in Firestore
 * @param userId - The user ID
 * @param userData - The user data to save
 */
export async function createUserDocument(
  userId: string,
  userData: Partial<UserDocument>,
): Promise<void> {
  try {
    const userRef = doc(db, 'users', userId);
    const timestamp = Date.now();

    await setDoc(userRef, {
      uid: userId,
      createdAt: timestamp,
      updatedAt: timestamp,
      ...Object.fromEntries(Object.entries(userData).filter(([_, v]) => v)),
    });

    console.log('User document created:', userId);
  } catch (error) {
    console.error('Error creating user document:', error);
    throw error;
  }
}

/**
 * Gets a user document from Firestore
 * @param userId - The user ID to fetch
 * @returns The user document data, or null if not found
 */
export async function getUserDocument(
  userId: string,
): Promise<UserDocument | null> {
  try {
    const userRef = doc(db, 'users', userId);
    const userSnap: DocumentSnapshot = await getDoc(userRef);

    if (userSnap.exists()) {
      return userSnap.data() as UserDocument;
    } else {
      return null;
    }
  } catch (error) {
    console.error('Error fetching user document:', error);
    throw error;
  }
}

/**
 * Updates an existing user document in Firestore
 * @param userId - The user ID to update
 * @param userData - The updated user data
 */
export async function updateUserDocument(
  userId: string,
  userData: Partial<Omit<UserDocument, 'uid' | 'createdAt'>>,
): Promise<void> {
  try {
    const userRef = doc(db, 'users', userId);
    await updateDoc(userRef, {
      ...userData,
      updatedAt: Date.now(),
    });
  } catch (error) {
    console.error('Error updating user document:', error);
    throw error;
  }
}

/**
 * Ensures a user document exists, creating it if it doesn't
 * @param userId - The user ID
 * @param userData - The user data to use if creating
 * @returns True if a new document was created, false if it already existed
 */
export async function ensureUserDocument(
  userId: string,
  userData: Partial<UserDocument>,
) {
  try {
    const exists = await userDocumentExists(userId);

    if (exists) return;

    await createUserDocument(userId, userData);
  } catch (error) {
    console.error('Error ensuring user document:', error);
    throw error;
  }
}

export async function addToWatchlist(userId: string, projectId: string) {
  try {
    const userRef = doc(db, 'users', userId);
    await updateDoc(userRef, {
      watchlist: arrayUnion(projectId),
    });
  } catch (error) {
    console.error('Error adding to watchlist:', error);
    throw error;
  }
}

export async function removeFromWatchlist(userId: string, projectId: string) {
  try {
    const userRef = doc(db, 'users', userId);
    await updateDoc(userRef, {
      watchlist: arrayRemove(projectId),
    });
  } catch (error) {
    console.error('Error removing from watchlist:', error);
    throw error;
  }
}

