     1→import {
     2→  collection,
     3→  getDocs,
     4→  orderBy,
     5→  query,
     6→  QuerySnapshot,
     7→  where,
     8→} from 'firebase/firestore';
     9→import { db } from './config';
    10→
    11→/**
    12→ * Fetches all transactions for a user from the root transactions collection
    13→ * @param userId - The user ID
    14→ * @returns Array of transactions
    15→ */
    16→export async function getUserTransactions(
    17→  userId: string,
    18→): Promise<Transaction[]> {
    19→  try {
    20→    const transactionsRef = collection(db, 'transactions');
    21→    const q = query(
    22→      transactionsRef,
    23→      where('userId', '==', userId),
    24→      orderBy('date', 'desc'),
    25→    );
    26→    const querySnapshot: QuerySnapshot = await getDocs(q);
    27→
    28→    const transactions: Transaction[] = [];
    29→    querySnapshot.forEach((doc) => {
    30→      transactions.push({
    31→        ...(doc.data() as Transaction),
    32→      });
    33→    });
    34→
    35→    return transactions;
    36→  } catch (error) {
    37→    console.error('Error fetching user transactions:', error);
    38→    throw error;
    39→  }
    40→}
    41→
    42→/**
    43→ * Calculates investment summary statistics
    44→ * @param transactions - Array of transactions
    45→ * @returns Investment summary with total invested, returns, and count
    46→ */
    47→export function calculateInvestmentSummary(transactions: Transaction[]): {
    48→  totalInvested: number;
    49→  totalReturns: number;
    50→  totalInvestments: number;
    51→} {
    52→  let totalInvested = 0;
    53→  let totalReturns = 0;
    54→  const totalInvestments = transactions.filter(
    55→    (t) => t.type === 'investment',
    56→  ).length;
    57→
    58→  transactions.forEach((transaction) => {
    59→    if (transaction.type === 'investment') {
    60→      totalInvested += transaction.amount;
    61→    } else if (transaction.type === 'return') {
    62→      totalReturns += transaction.amount;
    63→    }
    64→  });
    65→
    66→  return {
    67→    totalInvested,
    68→    totalReturns,
    69→    totalInvestments,
    70→  };
    71→}
    72→
    73→/**
    74→ * Groups transactions by project and calculates position data
    75→ * @param transactions - Array of transactions
    76→ * @returns Array of positions with project data
    77→ */
    78→export function calculatePositions(transactions: Transaction[]): {
    79→  projectId: string;
