import {
  collection,
  getDocs,
  orderBy,
  query,
  QuerySnapshot,
  where,
} from 'firebase/firestore';
import { db } from './config';

/**
 * Fetches all transactions for a user from the root transactions collection
 * @param userId - The user ID
 * @returns Array of transactions
 */
export async function getUserTransactions(
  userId: string,
): Promise<Transaction[]> {
  try {
    const transactionsRef = collection(db, 'transactions');
    const q = query(
      transactionsRef,
      where('userId', '==', userId),
      orderBy('date', 'desc'),
    );
    const querySnapshot: QuerySnapshot = await getDocs(q);

    const transactions: Transaction[] = [];
    querySnapshot.forEach((doc) => {
      transactions.push({
        ...(doc.data() as Transaction),
      });
    });

    return transactions;
  } catch (error) {
    console.error('Error fetching user transactions:', error);
    throw error;
  }
}

/**
 * Calculates investment summary statistics
 * @param transactions - Array of transactions
 * @returns Investment summary with total invested, returns, and count
 */
export function calculateInvestmentSummary(transactions: Transaction[]): {
  totalInvested: number;
  totalReturns: number;
  totalInvestments: number;
} {
  let totalInvested = 0;
  let totalReturns = 0;
  const totalInvestments = transactions.filter(
    (t) => t.type === 'investment',
  ).length;

  transactions.forEach((transaction) => {
    if (transaction.type === 'investment') {
      totalInvested += transaction.amount;
    } else if (transaction.type === 'return') {
      totalReturns += transaction.amount;
    }
  });

  return {
    totalInvested,
    totalReturns,
    totalInvestments,
  };
}

/**
 * Groups transactions by project and calculates position data
 * @param transactions - Array of transactions
 * @returns Array of positions with project data
 */
export function calculatePositions(transactions: Transaction[]): {
  projectId: string;
  projectName: string;
  costBasis: number;
  totalReturns: number;
  transactions: Transaction[];
  investmentDate: number;
}[] {
  const projectMap = new Map<
    string,
    {
      projectName: string;
      costBasis: number;
      totalReturns: number;
      transactions: Transaction[];
      investmentDate: number;
    }
  >();

  transactions.forEach((transaction) => {
    const existing = projectMap.get(transaction.projectId);

    if (existing) {
      if (transaction.type === 'investment') {
        existing.costBasis += transaction.amount;
        // Keep the earliest investment date
        if (transaction.date < existing.investmentDate) {
          existing.investmentDate = transaction.date;
        }
      } else if (transaction.type === 'return') {
        existing.totalReturns += transaction.amount;
      }
      existing.transactions.push(transaction);
    } else {
      projectMap.set(transaction.projectId, {
        projectName: transaction.projectName,
        costBasis: transaction.type === 'investment' ? transaction.amount : 0,
        totalReturns: transaction.type === 'return' ? transaction.amount : 0,
        transactions: [transaction],
        investmentDate: transaction.date,
      });
    }
  });

  return Array.from(projectMap.entries())
    .map(([projectId, data]) => ({
      projectId,
      ...data,
    }))
    .sort((a, b) => b.investmentDate - a.investmentDate);
}

