import {
  addDoc,
  collection,
  doc,
  DocumentSnapshot,
  getDoc,
  getDocs,
  QuerySnapshot,
  updateDoc,
} from 'firebase/firestore';
import { db } from './server';

/**
 * Fetches a single project from Firestore by its ID
 * @param projectId - The ID of the project to fetch
 * @returns The project data with its ID, or null if not found
 */
export async function getProjectById(
  projectId: string,
): Promise<(Project & { id: string }) | null> {
  try {
    const projectRef = doc(db, 'projects', projectId);
    const projectSnap: DocumentSnapshot = await getDoc(projectRef);

    if (projectSnap.exists()) {
      return {
        id: projectSnap.id,
        ...projectSnap.data(),
      } as Project & { id: string };
    } else {
      return null;
    }
  } catch (error) {
    console.error('Error fetching project:', error);
    throw error;
  }
}

/**
 * Fetches all projects from Firestore
 * @returns An array of all projects with their IDs
 */
export async function getAllProjects(): Promise<
  Array<Project & { id: string }>
> {
  try {
    const projectsCollection = collection(db, 'projects');
    const projectsSnapshot: QuerySnapshot = await getDocs(projectsCollection);

    return projectsSnapshot.docs.map((doc) => ({
      id: doc.id,
      ...doc.data(),
    })) as Array<Project & { id: string }>;
  } catch (error) {
    console.error('Error fetching projects:', error);
    throw error;
  }
}

/**
 * Creates a new project in Firestore
 * @param projectData - The project data to save
 * @returns The created project ID
 */
export async function createProject(
  projectData: Omit<Project, 'id'>,
): Promise<string> {
  try {
    const projectRef = collection(db, 'projects');
    const docRef = await addDoc(projectRef, {
      ...projectData,
      createdAt: Date.now(),
    });
    return docRef.id;
  } catch (error) {
    console.error('Error creating project:', error);
    throw error;
  }
}

/**
 * Updates an existing project in Firestore
 * @param projectId - The ID of the project to update
 * @param projectData - The updated project data
 */
export async function updateProject(
  projectId: string,
  projectData: Partial<Omit<Project, 'id'>>,
): Promise<void> {
  try {
    const projectRef = doc(db, 'projects', projectId);
    await updateDoc(projectRef, projectData);
  } catch (error) {
    console.error('Error updating project:', error);
    throw error;
  }
}

/**
 * Checks if a user has admin role
 * @param userId - The ID of the user to check
 * @returns True if the user has admin role, false otherwise
 */
export async function isUserAdmin(userId: string): Promise<boolean> {
  try {
    const userRef = doc(db, 'users', userId);
    const userSnap: DocumentSnapshot = await getDoc(userRef);

    if (userSnap.exists()) {
      const userData = userSnap.data();
      return userData?.role === 'admin';
    }
    return false;
  } catch (error) {
    console.error('Error checking admin status:', error);
    return false;
  }
}

