'use client';

import { formatPrice } from '@modules/shared/utils/formatPrice';
import { format } from 'date-fns/format';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from 'modules/shared/table';
import { FC, useEffect, useState } from 'react';
import { collection, query, where, getDocs } from 'firebase/firestore';
import { db } from 'lib/firebase/config';
import { Button } from '@modules/shared/button';
import { Plus } from 'lucide-react';
import { AddReturnModal } from './AddReturnModal';

interface ReturnsProps {
  project: Project & { id: string };
}

export const Returns: FC<ReturnsProps> = ({ project }) => {
  const [returns, setReturns] = useState<Transaction[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const fetchReturns = async () => {
    try {
      setLoading(true);
      const transactionsRef = collection(db, 'transactions');
      const q = query(
        transactionsRef,
        where('projectId', '==', project.id),
        where('type', '==', 'return'),
      );

      const querySnapshot = await getDocs(q);
      const fetchedReturns: Transaction[] = [];

      querySnapshot.forEach((doc) => {
        fetchedReturns.push(doc.data() as Transaction);
      });

      // Sort by date descending
      fetchedReturns.sort((a, b) => b.date - a.date);

      setReturns(fetchedReturns);
    } catch (error) {
      console.error('Error fetching returns:', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchReturns();
  }, [project.id]);

  const handleReturnAdded = () => {
    fetchReturns();
  };

  const totalReturns = returns.reduce((sum, ret) => sum + ret.amount, 0);

  if (loading) {
    return (
      <div className="w-full bg-white rounded-[16px] shadow-lg p-40 flex items-center justify-center">
        <p className="text-gray-600">Loading returns...</p>
      </div>
    );
  }

  if (returns.length === 0) {
    return (
      <>
        <div className="w-full bg-white rounded-[16px] shadow-lg p-40 flex flex-col items-center justify-center">
          <p className="text-gray-600 mb-8">No returns yet</p>
          <p className="text-sm text-gray-500 mb-16">
            Returns for this project will appear here
          </p>
          <Button onClick={() => setIsModalOpen(true)}>
            <Plus className="mr-2 h-4 w-4" />
            Add Return
          </Button>
        </div>
        <AddReturnModal
          open={isModalOpen}
          onOpenChange={setIsModalOpen}
          project={project}
          onReturnAdded={handleReturnAdded}
        />
      </>
    );
  }

  return (
    <>
      <div className="w-full bg-white rounded-[16px] shadow-lg p-24">
        <div className="flex justify-between items-center mb-20">
          <h2 className="text-[clamp(20px,22px)] leading-[clamp(24px,28px)] font-semibold">
            Returns
          </h2>
          <div className="flex items-center gap-16">
            <div className="text-right">
              <p className="text-sm text-gray-600 mb-2">Total Returns</p>
              <p className="text-xl font-bold text-green-600">
                {formatPrice(totalReturns)}
              </p>
            </div>
            <Button onClick={() => setIsModalOpen(true)} size="small">
              <Plus className="mr-2 h-4 w-4" />
              Add Return
            </Button>
          </div>
        </div>

      <Table>
        <TableHeader>
          <TableRow className="h-60">
            <TableHead className="font-semibold">Date</TableHead>
            <TableHead className="font-semibold">Description</TableHead>
            <TableHead className="font-semibold">Amount</TableHead>
            <TableHead className="font-semibold">User ID</TableHead>
            <TableHead className="font-semibold">User Email</TableHead>
            <TableHead className="font-semibold">Account</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {returns.map((returnTransaction, index) => (
            <TableRow
              key={`${returnTransaction.projectId}-${index}`}
              className="h-60">
              <TableCell className="text-sm">
                {format(returnTransaction.date, 'MMM d, yyyy')}
              </TableCell>
              <TableCell className="text-sm text-gray-600">
                {returnTransaction.description}
              </TableCell>
              <TableCell className="text-sm font-medium text-green-600">
                + {formatPrice(returnTransaction.amount)}
              </TableCell>
              <TableCell className="text-xs text-gray-600 font-mono">
                {returnTransaction.userId}
              </TableCell>
              <TableCell className="text-sm text-gray-600">
                {returnTransaction.userEmail}
              </TableCell>
              <TableCell className="text-sm text-gray-600">
                {returnTransaction.accountName}
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
    <AddReturnModal
      open={isModalOpen}
      onOpenChange={setIsModalOpen}
      project={project}
      onReturnAdded={handleReturnAdded}
    />
    </>
  );
};

