'use client';

import { Button } from '@modules/shared/button';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@modules/shared/dialog';
import { Input } from '@modules/shared/input';
import { Label } from '@modules/shared/label';

import { Textarea } from '@modules/shared/textarea';
import { formatPrice } from '@modules/shared/utils/formatPrice';
import { collection, getDocs, query, where } from 'firebase/firestore';
import { db } from 'lib/firebase/config';
import { createReturnTransaction } from 'lib/firebase/transaction-actions';
import { FC, useEffect, useState } from 'react';
import { toast } from 'sonner';

interface AddReturnModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  project: Project & { id: string };
  onReturnAdded: () => void;
}

interface Investor {
  userId: string;
  userEmail: string;
  accountName: string;
  totalInvested: number;
}

export const AddReturnModal: FC<AddReturnModalProps> = ({
  open,
  onOpenChange,
  project,
  onReturnAdded,
}) => {
  const [investors, setInvestors] = useState<Investor[]>([]);
  const [selectedInvestorId, setSelectedInvestorId] = useState<string>('');
  const [amount, setAmount] = useState<number>(0);
  const [description, setDescription] = useState('');
  const [loading, setLoading] = useState(false);
  const [loadingInvestors, setLoadingInvestors] = useState(false);

  useEffect(() => {
    if (open) {
      fetchInvestors();
    }
  }, [open, project.id]);

  const fetchInvestors = async () => {
    try {
      setLoadingInvestors(true);
      const transactionsRef = collection(db, 'transactions');
      const q = query(
        transactionsRef,
        where('projectId', '==', project.id),
        where('type', '==', 'investment'),
      );

      const querySnapshot = await getDocs(q);
      const investorMap = new Map<string, Investor>();

      querySnapshot.forEach((doc) => {
        const transaction = doc.data() as Transaction;
        const existing = investorMap.get(transaction.userId);

        if (existing) {
          existing.totalInvested += transaction.amount;
        } else {
          investorMap.set(transaction.userId, {
            userId: transaction.userId,
            userEmail: transaction.userEmail,
            accountName: transaction.accountName,
            totalInvested: transaction.amount,
          });
        }
      });

      setInvestors(Array.from(investorMap.values()));
    } catch (error) {
      console.error('Error fetching investors:', error);
      toast.error('Failed to load investors');
    } finally {
      setLoadingInvestors(false);
    }
  };

  const handleAddReturn = async () => {
    if (!selectedInvestorId) {
      toast.error('Please select an investor');
      return;
    }

    if (!amount || amount <= 0) {
      toast.error('Please enter a valid return amount');
      return;
    }

    if (!description.trim()) {
      toast.error('Please enter a description');
      return;
    }

    const selectedInvestor = investors.find(
      (inv) => inv.userId === selectedInvestorId,
    );

    if (!selectedInvestor) {
      toast.error('Selected investor not found');
      return;
    }

    try {
      setLoading(true);

      await createReturnTransaction(
        project.id,
        project.name,
        amount,
        selectedInvestor.accountName,
        description.trim(),
        selectedInvestor.userId,
        selectedInvestor.userEmail,
      );

      toast.success('Return added successfully');
      onOpenChange(false);
      onReturnAdded();

      // Reset form
      setSelectedInvestorId('');
      setAmount(0);
      setDescription('');
    } catch (error) {
      console.error('Error adding return:', error);
      toast.error('Failed to add return. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const selectedInvestor = investors.find(
    (inv) => inv.userId === selectedInvestorId,
  );

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[500px]">
        <DialogHeader>
          <DialogTitle className="text-2xl font-semibold">
            Add Return
          </DialogTitle>
          <DialogDescription>
            Add a return payment to an investor for {project.name}
          </DialogDescription>
        </DialogHeader>

        <div className="grid gap-20 py-16">
          {loadingInvestors ? (
            <div className="py-20 text-center text-gray-600">
              Loading investors...
            </div>
          ) : investors.length === 0 ? (
            <div className="py-20 text-center text-gray-600">
              No investors found for this project
            </div>
          ) : (
            <>
              <div className="grid gap-8">
                <Label htmlFor="investor">Select Investor *</Label>
                <select
                  id="investor"
                  value={selectedInvestorId}
                  onChange={(e) => setSelectedInvestorId(e.target.value)}
                  disabled={loading}
                  className="block w-full p-10 border border-gray-300 rounded bg-white">
                  <option value="">Select an investor</option>
                  {investors.map((investor) => (
                    <option key={investor.userId} value={investor.userId}>
                      {investor.userEmail} -{' '}
                      {formatPrice(investor.totalInvested)} invested
                    </option>
                  ))}
                </select>
              </div>

              {selectedInvestor && (
                <div className="p-12 bg-gray-50 rounded-lg">
                  <p className="text-sm text-gray-600 mb-4">
                    <strong>Account:</strong> {selectedInvestor.accountName}
                  </p>
                  <p className="text-sm text-gray-600">
                    <strong>Total Invested:</strong>{' '}
                    {formatPrice(selectedInvestor.totalInvested)}
                  </p>
                </div>
              )}

              <div className="grid gap-8">
                <Label htmlFor="amount">Return Amount ($) *</Label>
                <Input
                  variant="small"
                  id="amount"
                  type="number"
                  step="0.01"
                  min="0"
                  placeholder="Enter return amount"
                  value={amount || ''}
                  onChange={(e) => setAmount(Number(e.target.value))}
                  disabled={loading}
                />
              </div>

              <div className="grid gap-8">
                <Label htmlFor="description">Description *</Label>
                <Textarea
                  id="description"
                  placeholder="Enter return description (e.g., Q1 dividend payment)"
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  disabled={loading}
                  rows={4}
                />
              </div>
            </>
          )}
        </div>

        <DialogFooter className="flex items-center justify-between w-full gap-12">
          <Button
            type="button"
            variant="outline"
            onClick={() => onOpenChange(false)}
            disabled={loading}
            className="flex-1">
            Cancel
          </Button>
          <Button
            type="button"
            onClick={handleAddReturn}
            disabled={loading || loadingInvestors || investors.length === 0}
            className="flex-1">
            {loading ? 'Adding...' : 'Add Return'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

