'use client';

import { formatPrice } from '@modules/shared/utils/formatPrice';
import { format } from 'date-fns/format';
import { collection, getDocs, orderBy, query, where } from 'firebase/firestore';
import { db } from 'lib/firebase/config';
import {
  Pagination,
  PaginationContent,
  PaginationEllipsis,
  PaginationItem,
  PaginationLink,
  PaginationNext,
  PaginationPrevious,
} from 'modules/shared/pagination';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from 'modules/shared/table';
import { FC, useEffect, useState } from 'react';

interface AdminTransactionsProps {
  project: Project & { id: string };
}

export const AdminTransactions: FC<AdminTransactionsProps> = ({ project }) => {
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;

  useEffect(() => {
    const fetchTransactions = async () => {
      try {
        setLoading(true);
        const transactionsRef = collection(db, 'transactions');
        const q = query(
          transactionsRef,
          where('projectId', '==', project.id),
          orderBy('date', 'desc'),
        );

        const querySnapshot = await getDocs(q);
        const fetchedTransactions: Transaction[] = [];

        querySnapshot.forEach((doc) => {
          fetchedTransactions.push(doc.data() as Transaction);
        });

        setTransactions(fetchedTransactions);
      } catch (error) {
        console.error('Error fetching transactions:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchTransactions();
  }, [project.id]);

  // Calculate pagination
  const totalPages = Math.ceil(transactions.length / itemsPerPage);
  const startIndex = (currentPage - 1) * itemsPerPage;
  const endIndex = startIndex + itemsPerPage;
  const paginatedTransactions = transactions.slice(startIndex, endIndex);

  const handlePageChange = (page: number) => {
    setCurrentPage(page);
  };

  const generatePageNumbers = () => {
    const pages: (number | 'ellipsis')[] = [];

    if (totalPages <= 7) {
      for (let i = 1; i <= totalPages; i++) {
        pages.push(i);
      }
    } else {
      pages.push(1);

      if (currentPage > 3) {
        pages.push('ellipsis');
      }

      const start = Math.max(2, currentPage - 1);
      const end = Math.min(totalPages - 1, currentPage + 1);

      for (let i = start; i <= end; i++) {
        pages.push(i);
      }

      if (currentPage < totalPages - 2) {
        pages.push('ellipsis');
      }

      pages.push(totalPages);
    }

    return pages;
  };

  const totalInvestments = transactions
    .filter((t) => t.type === 'investment')
    .reduce((sum, t) => sum + t.amount, 0);

  const totalReturns = transactions
    .filter((t) => t.type === 'return')
    .reduce((sum, t) => sum + t.amount, 0);

  if (loading) {
    return (
      <div className="w-full bg-white rounded-[16px] shadow-lg p-40 flex items-center justify-center">
        <p className="text-gray-600">Loading transactions...</p>
      </div>
    );
  }

  if (transactions.length === 0) {
    return (
      <div className="w-full bg-white rounded-[16px] shadow-lg p-40 flex flex-col items-center justify-center">
        <p className="text-gray-600 mb-8">No transactions yet</p>
        <p className="text-sm text-gray-500">
          Transactions for this project will appear here
        </p>
      </div>
    );
  }

  return (
    <div className="w-full bg-white rounded-[16px] shadow-lg p-24">
      <div className="mb-20">
        <h2 className="text-[clamp(20px,22px)] leading-[clamp(24px,28px)] font-semibold mb-12">
          All Transactions
        </h2>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-16">
          <div className="p-16 bg-gray-50 rounded-lg">
            <p className="text-sm text-gray-600 mb-4">Total Investments</p>
            <p className="text-xl font-bold text-blue-600">
              {formatPrice(totalInvestments)}
            </p>
          </div>
          <div className="p-16 bg-gray-50 rounded-lg">
            <p className="text-sm text-gray-600 mb-4">Total Returns</p>
            <p className="text-xl font-bold text-green-600">
              {formatPrice(totalReturns)}
            </p>
          </div>
          <div className="p-16 bg-gray-50 rounded-lg">
            <p className="text-sm text-gray-600 mb-4">Net Flow</p>
            <p
              className={`text-xl font-bold ${
                totalReturns - totalInvestments >= 0
                  ? 'text-green-600'
                  : 'text-red-600'
              }`}>
              {formatPrice(totalReturns - totalInvestments)}
            </p>
          </div>
        </div>
      </div>

      <Table>
        <TableHeader>
          <TableRow className="h-60">
            <TableHead className="font-semibold">Date</TableHead>
            <TableHead className="font-semibold">Type</TableHead>
            <TableHead className="font-semibold">Description</TableHead>
            <TableHead className="font-semibold">Amount</TableHead>
            <TableHead className="font-semibold">User ID</TableHead>
            <TableHead className="font-semibold">User Email</TableHead>
            <TableHead className="font-semibold">Account</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {paginatedTransactions.map((transaction, index) => (
            <TableRow
              key={`${transaction.projectId}-${index}`}
              className="h-60">
              <TableCell className="text-sm">
                {format(transaction.date, 'MMM d, yyyy')}
              </TableCell>
              <TableCell>
                <span
                  className={`inline-flex items-center px-2.5 py-0.5 rounded text-xs font-medium capitalize ${
                    transaction.type === 'return'
                      ? 'bg-green-100 text-green-800'
                      : 'bg-blue-100 text-blue-800'
                  }`}>
                  {transaction.type}
                </span>
              </TableCell>
              <TableCell className="text-sm text-gray-600">
                {transaction.description}
              </TableCell>
              <TableCell
                className={`text-sm font-medium ${
                  transaction.type === 'return'
                    ? 'text-green-600'
                    : 'text-blue-600'
                }`}>
                {transaction.type === 'return' ? '+' : '-'}{' '}
                {formatPrice(transaction.amount)}
              </TableCell>
              <TableCell className="text-xs text-gray-600 font-mono">
                {transaction.userId}
              </TableCell>
              <TableCell className="text-sm text-gray-600">
                {transaction.userEmail}
              </TableCell>
              <TableCell className="text-sm text-gray-600">
                {transaction.accountName}
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="mt-6">
          <Pagination className="w-full">
            <PaginationContent className="w-full flex">
              <PaginationItem className="mr-auto">
                <PaginationPrevious
                  href="#"
                  onClick={(e) => {
                    e.preventDefault();
                    if (currentPage > 1) handlePageChange(currentPage - 1);
                  }}
                  className={
                    currentPage === 1
                      ? 'pointer-events-none opacity-50'
                      : 'cursor-pointer'
                  }
                />
              </PaginationItem>

              {generatePageNumbers().map((page, index) =>
                page === 'ellipsis' ? (
                  <PaginationItem key={`ellipsis-${index}`}>
                    <PaginationEllipsis />
                  </PaginationItem>
                ) : (
                  <PaginationItem key={page}>
                    <PaginationLink
                      href="#"
                      onClick={(e) => {
                        e.preventDefault();
                        handlePageChange(page);
                      }}
                      isActive={currentPage === page}
                      className="cursor-pointer">
                      {page}
                    </PaginationLink>
                  </PaginationItem>
                ),
              )}

              <PaginationItem className="ml-auto">
                <PaginationNext
                  href="#"
                  onClick={(e) => {
                    e.preventDefault();
                    if (currentPage < totalPages)
                      handlePageChange(currentPage + 1);
                  }}
                  className={
                    currentPage === totalPages
                      ? 'pointer-events-none opacity-50'
                      : 'cursor-pointer'
                  }
                />
              </PaginationItem>
            </PaginationContent>
          </Pagination>
        </div>
      )}
    </div>
  );
};

